export function parseLine(line) {
  const fields = []
  let field = ""
  let inQuotes = false
  for (let i = 0; i < line.length; i++) {
    const char = line[i]
    if (inQuotes) {
      if (char === '"') {
        if (line[i+1] === '"') { field += '"'; i++ } else { inQuotes = false }
      } else field += char
    } else {
      if (char === '"') inQuotes = true
      else if (char === ',') { fields.push(field); field = "" }
      else field += char
    }
  }
  fields.push(field)
  return fields
}
